  mkdirSync(home, { recursive: true });
  const failMcp = opts.failMcp
    ? `
if [ "$1" = mcp ]; then
  echo "mcp failed" >&2
370→  exit 1
fi
`
    : "";
  writeFileSync(
    join(bin, "hermes"),
    `#!/bin/sh
echo "$@" >> "${log}"
if [ "$1" = cron ] && [ "$2" = list ]; then
  printf '%s' '${listOut.replace(/'/g, "")}'
380→fi
${failMcp}
exit 0
`,
  );
  chmodSync(join(bin, "hermes"), 0o755);
  return { bin, log };
}

